/**
 * Jinx Alchemist + Summoner: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Alchemist
 * Wiki: https://wiki.bloodontheclocktower.com/Summoner
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in. Each test quotes the jinx as
 * the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { analyseSelection, randomSelection, type BagSelection } from '#lib/core/rules/bag-plan.ts';
import { gameEnds } from '#lib/core/rules/game-end.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { gainedEnd } from '#lib/core/rules/jinx-effects.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { changeableSeats, characterChanger } from '#lib/core/rules/becomes.ts';
import { abilityHolders } from '#lib/core/rules/gained-abilities.ts';
import { evilInfoNotesLeftOut, picksCharacterOnlyBy } from '#lib/core/rules/holder-jinxes.ts';
import { nightOrder } from '#lib/core/rules/night-order.ts';
import { alchemistAs, scriptOf } from './alchemist.test-support.ts';

const pick = (...ids: string[]): BagSelection => Object.fromEntries(ids.map((id) => [id, 1]));

describe('Alchemist + Summoner jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alchemist', 'summoner');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alchemist')?.name).toBe('Alchemist');
		expect(data.byId.get('summoner')?.name).toBe('Summoner');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alchemist', 'summoner'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alchemist'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['summoner'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: an Alchemist with the Summoner ability means no Demon at
	// setup. The Alchemist picks its Minion ability only once the tokens are out, so at the bag
	// a game with no Demon is allowed as well as the usual one, and nothing is required.
	describe('[No Demon] when the Alchemist has the Summoner ability', () => {
		const lookup = (id: string) => data.byId.get(id);
		const script = [
			'alchemist',
			'chef',
			'empath',
			'monk',
			'soldier',
			'mayor',
			'saint',
			'poisoner',
			'summoner',
			'imp'
		];
		const analyse = (selection: BagSelection, order = script) =>
			analyseSelection({ players: 7, selection, scriptOrder: order, lookup });

		it("is data in the Alchemist's rules", () => {
			// Wiki: "The Alchemist-Summoner does not get bluffs, and chooses which Demon but not which player. If they die before this happens, evil wins. [No Demon]"
			expect(jinxRulesBetween('alchemist', 'summoner')).toEqual({
				storytellerChooses: { what: 'player', when: ['has-partner-ability'] },
				endsGame: { kind: 'partner-end', winner: 'evil' },
				partnerSetup: {},
				noBluffs: {}
			});
		});

		it('allows a bag with no Demon and an extra Townsfolk, or the usual one', () => {
			// Wiki: "[No Demon]"
			const none = analyse(
				pick('alchemist', 'chef', 'empath', 'monk', 'soldier', 'mayor', 'poisoner')
			);
			expect(none.expected.demon).toEqual([0, 1]);
			expect(none.warnings).toEqual([]);
			expect(none.reasons.demon).toEqual(['Alchemist with the Summoner ability: No Demon']);
			const usual = analyse(
				pick('alchemist', 'chef', 'empath', 'monk', 'soldier', 'poisoner', 'imp')
			);
			expect(usual.warnings).toEqual([]);
		});

		it('changes nothing without the Alchemist, or with the Summoner off the script', () => {
			// Wiki: "The Alchemist-Summoner"
			const noAlchemist = analyse(
				pick('chef', 'empath', 'monk', 'soldier', 'mayor', 'poisoner', 'imp')
			);
			expect(noAlchemist.expected.demon).toEqual([1]);
			const offScript = analyse(
				pick('alchemist', 'chef', 'empath', 'monk', 'soldier', 'poisoner', 'imp'),
				script.filter((id) => id !== 'summoner')
			);
			expect(offScript.expected.demon).toEqual([1]);
			expect(offScript.modifiers).toEqual([]);
		});

		it('keeps a Demon in a random bag', () => {
			// Wiki: "[No Demon]"
			const scriptCharacters = script.map((id) => lookup(id)!);
			for (const r of [0, 0.3, 0.6, 0.99]) {
				const selection = randomSelection({
					players: 7,
					selection: pick('alchemist'),
					scriptCharacters,
					scriptOrder: script,
					lookup,
					random: () => r
				});
				expect(selection.imp).toBe(1);
			}
		});
	});

	// The Summoner part (L119, L121): the Alchemist-Summoner who dies before a Demon is made loses
	// the game for good, not evil; their gained Summoner ability runs at its step on Night 3
	// (`abilityHolders`), they pick the Demon, the Storyteller the player, and they get no bluffs.
	describe('the Alchemist-Summoner who dies first, and who picks the player', () => {
		const base = alchemistAs('summoner', ['chef', 'empath', 'monk', 'poisoner']);
		const ends = (s: typeof base) =>
			gameEnds(s.game, s.characters).filter((e) => e.rule === 'dead-without-demon');

		it('gives the Alchemist-Summoner the Summoner end with evil as the winner', () => {
			// Wiki: "If they die before this happens, evil wins."
			expect(gainedEnd(base.game, base.seat(0), base.characters)).toEqual({
				partner: 'summoner',
				winner: 'evil'
			});
		});

		it('ends the game for evil when they die before a Demon is made', () => {
			// Wiki: "If they die before this happens, evil wins."
			expect(ends(base)).toEqual([]);
			expect(ends(base.dies(0))).toMatchObject([
				{ rule: 'dead-without-demon', winner: 'evil', characterId: 'summoner' }
			]);
		});

		it('ends nothing once a Demon is in play', () => {
			// Wiki: "If they die before this happens"
			expect(ends(base.becomes('chef', 'imp', 'evil').dies(0))).toEqual([]);
		});

		const night3 = (s: typeof base) => s.reminder(0, 'summoner', 'Night 3');

		it('runs the gained Summoner ability at its step on Night 3, as the Summoner would', () => {
			// Wiki: "The Alchemist-Summoner does not get bluffs, and chooses which Demon but not which player."
			expect(characterChanger(base.game, 'summoner', base.characters)).toBe(undefined);
			expect(
				characterChanger(base.reminder(0, 'summoner', 'Night 2').game, 'summoner', base.characters)
			).toBe(undefined);
			const s = night3(base);
			expect(abilityHolders(s.game, 'summoner', s.characters)).toEqual([s.seat(0)]);
			expect(characterChanger(s.game, 'summoner', s.characters)).toBe(s.seat(0));
			expect(changeableSeats(s.game, 'summoner', s.characters)).toContain(s.seat('chef'));
		});

		it('lets the Alchemist-Summoner choose the Demon, the Storyteller the player', () => {
			// Wiki: "chooses which Demon but not which player"
			const s = night3(base);
			expect(picksCharacterOnlyBy(s.game, 'summoner', s.characters)).toBe('alchemist');
			// The player the Storyteller picks becomes the evil Demon chosen.
			const made = s.do((at) => ({
				type: 'AssignCharacter',
				seatId: at.seat('chef'),
				characterId: 'imp',
				alignment: 'evil',
				by: 'summoner'
			}));
			expect(made.game.seats[made.seat('chef')]).toMatchObject({
				characterId: 'imp',
				alignment: 'evil'
			});
			expect(ends(made.dies(0))).toEqual([]);
		});

		it('leaves the choice of player to the real Summoner, off the jinx', () => {
			// Wiki: "The Alchemist-Summoner"
			const real = scenario(['summoner', 'chef', 'empath', 'monk', 'poisoner'], {
				script: scriptOf(['alchemist', 'summoner', 'chef', 'empath', 'monk', 'poisoner'])
			}).reminder('summoner', 'summoner', 'Night 3');
			expect(characterChanger(real.game, 'summoner', real.characters)).toBe(real.seat('summoner'));
			expect(picksCharacterOnlyBy(real.game, 'summoner', real.characters)).toBe(undefined);
		});

		describe('no bluffs', () => {
			const data = committedGameData();
			const demonInfoNotes = (s: typeof base) => {
				const inPlay = s.game.seating.flatMap((id) => {
					const c = s.characters.get(s.game.seats[id].characterId ?? '');
					return c ? [c] : [];
				});
				const order = nightOrder({
					night: 'first',
					sheet: data.nightSheet,
					inPlay,
					players: 7,
					noAbility: evilInfoNotesLeftOut(s.game, s.characters)
				});
				return order.steps.find((step) => step.id === 'demoninfo')?.notes ?? [];
			};

			it("leaves the Summoner's bluffs note out of Demon info for the Alchemist-Summoner", () => {
				// Wiki: "The Alchemist-Summoner does not get bluffs"
				expect(evilInfoNotesLeftOut(base.game, base.characters)).toContain('summoner');
				expect(demonInfoNotes(base).some((n) => n.startsWith('Summoner:'))).toBe(false);
			});

			it('keeps it for the real Summoner', () => {
				// Wiki: "The Alchemist-Summoner does not get bluffs"
				const real = scenario(['summoner', 'chef', 'empath', 'monk', 'poisoner'], {
					script: scriptOf(['alchemist', 'summoner', 'chef', 'empath', 'monk', 'poisoner'])
				});
				expect(evilInfoNotesLeftOut(real.game, real.characters)).not.toContain('summoner');
				expect(demonInfoNotes(real).some((n) => n.startsWith('Summoner:'))).toBe(true);
			});
		});
	});
});
